B.Ka=new A.bz("dart-04-operadores","Dart b\xe1sico","04 \xb7 Operadores","Principiante","Practica operadores aritm\xe9ticos, comparaci\xf3n, asignaci\xf3n, l\xf3gicos y ternarios.","Los operadores permiten calcular, comparar y construir condiciones.","void main() {\n  var a = 10;\n  var b = 3;\n  print(a + b);\n  print(a - b);\n  print(a * b);\n  print(a / b);\n  print(a ~/ b);\n  print(a % b);\n\n  final cumple = a >= 10 && b != 0;\n  final mensaje = cumple ? 'V\xe1lido' : 'No v\xe1lido';\n  print(mensaje);\n}",B.Wa,"Determina si una persona puede entrar a un evento seg\xfan edad y entrada v\xe1lida.",B.UA,4284524026)
